const apiResponse = $input.item.json;

if (!apiResponse.results || apiResponse.results.length === 0) {
  return {
    json: {
      status: "no_results",
      message: "متأسفانه محصولی با این مشخصات پیدا نشد."
    }
  };
}

let message = ` ${apiResponse.results.length} محصول پیدا شد:\n\n`;

apiResponse.results.forEach((product, index) => {
  message += `${index + 1}. ${product.name}\n`;
  if (product.author_or_type_or_age) {
    message += ` ${product.author_or_type_or_age}\n`;
  }
  if (product.publisher_or_brand) {
    message += ` ${product.publisher_or_brand}\n`;
  }
  if (product.price) {
    message += ` ${product.price.toLocaleString()} تومان\n`;
  }
  message += `\n`;
});

return {
  json: {
    status: "ok",
    message
  }
};

// ==========================================
// Build Stock API Payload (CANONICAL + SAFE)
// Works with BOTH old & new extractor shapes
// ==========================================

const input = $json;

// -------- helpers --------
const clean = (v) => (typeof v === "string" ? v.trim() : "");
const nonEmpty = (v) => typeof v === "string" && v.trim().length > 0;

const toStringArray = (v) => {
  if (Array.isArray(v)) return v.map(clean).filter((x) => x.length > 0);
  if (typeof v === "string") {
    // split on comma / Arabic comma / Persian comma
    return v
      .split(/[,\u060C\u061B]+/g)
      .map(clean)
      .filter((x) => x.length > 0);
  }
  return [];
};

const uniq = (arr) => [...new Set((arr || []).map(clean).filter((x) => x.length > 0))];

// -------- parse extractor output --------
// Sometimes Extract Intent returns JSON as a string in input.text
let parsed = input;
if (typeof input?.text === "string") {
  try {
    parsed = JSON.parse(input.text);
  } catch (e) {
    // if it isn't valid JSON, keep input as-is
    parsed = input;
  }
}

// -------- canonical payload skeleton (DO NOT CHANGE KEYS) --------
const payload = {
  version: "1.0",
  query_text: "",
  category_code: null,
  uploaded_only: true,
  filters: {
    name: { include: [], exclude: [] },
    author_or_type_or_age: { include: [], exclude: [] },
    translator_or_playtime: { include: [], exclude: [] },
    publisher_or_brand: { include: [], exclude: [] },
    group_main: { include: [], exclude: [] },
    groupfamily_tags: { include_all: [], include_any: [], exclude: [] },
    price: { min: null, max: null },
    stock: { in_stock_only: true },
  },
  sort: { by: "relevance", direction: "desc" },
  limit: 10,
  ui: {
    need_clarification: false,
    clarification_question: null,
  },
};

// -------- copy over ui safely --------
if (parsed?.ui && typeof parsed.ui === "object") {
  if (typeof parsed.ui.need_clarification === "boolean") {
    payload.ui.need_clarification = parsed.ui.need_clarification;
  }
  if (typeof parsed.ui.clarification_question === "string") {
    payload.ui.clarification_question = parsed.ui.clarification_question;
  }
}

// -------- category_code (string or array) --------
let cat = parsed?.category_code ?? parsed?.filters?.category_code ?? null;
if (Array.isArray(cat)) cat = cat[0] ?? null; // API usually expects one
payload.category_code = nonEmpty(cat) ? clean(cat) : null;

// -------- uploaded_only / stock safety --------
payload.uploaded_only = true;
payload.filters.stock = { in_stock_only: true };

// -------- price --------
if (parsed?.filters?.price && typeof parsed.filters.price === "object") {
  payload.filters.price.min = parsed.filters.price.min ?? null;
  payload.filters.price.max = parsed.filters.price.max ?? null;
}

// ==================================================
// 1) NEW canonical extractor format (preferred)
// ==================================================
if (parsed?.filters && typeof parsed.filters === "object") {
  // name
  if (parsed.filters.name) {
    payload.filters.name.include = uniq([
      ...payload.filters.name.include,
      ...toStringArray(parsed.filters.name.include),
    ]);
    payload.filters.name.exclude = uniq([
      ...payload.filters.name.exclude,
      ...toStringArray(parsed.filters.name.exclude),
    ]);
  }

  // author/type/age
  if (parsed.filters.author_or_type_or_age) {
    payload.filters.author_or_type_or_age.include = uniq([
      ...payload.filters.author_or_type_or_age.include,
      ...toStringArray(parsed.filters.author_or_type_or_age.include),
    ]);
    payload.filters.author_or_type_or_age.exclude = uniq([
      ...payload.filters.author_or_type_or_age.exclude,
      ...toStringArray(parsed.filters.author_or_type_or_age.exclude),
    ]);
  }

  // translator/playtime
  if (parsed.filters.translator_or_playtime) {
    payload.filters.translator_or_playtime.include = uniq([
      ...payload.filters.translator_or_playtime.include,
      ...toStringArray(parsed.filters.translator_or_playtime.include),
    ]);
    payload.filters.translator_or_playtime.exclude = uniq([
      ...payload.filters.translator_or_playtime.exclude,
      ...toStringArray(parsed.filters.translator_or_playtime.exclude),
    ]);
  }

  // publisher/brand
  if (parsed.filters.publisher_or_brand) {
    payload.filters.publisher_or_brand.include = uniq([
      ...payload.filters.publisher_or_brand.include,
      ...toStringArray(parsed.filters.publisher_or_brand.include),
    ]);
    payload.filters.publisher_or_brand.exclude = uniq([
      ...payload.filters.publisher_or_brand.exclude,
      ...toStringArray(parsed.filters.publisher_or_brand.exclude),
    ]);
  }

  // group_main
  if (parsed.filters.group_main) {
    payload.filters.group_main.include = uniq([
      ...payload.filters.group_main.include,
      ...toStringArray(parsed.filters.group_main.include),
    ]);
    payload.filters.group_main.exclude = uniq([
      ...payload.filters.group_main.exclude,
      ...toStringArray(parsed.filters.group_main.exclude),
    ]);
  }

  // ✅ groupfamily_tags (KEEP THIS WORKING)
  if (parsed.filters.groupfamily_tags) {
    const g = parsed.filters.groupfamily_tags;
    payload.filters.groupfamily_tags.include_all = uniq([
      ...payload.filters.groupfamily_tags.include_all,
      ...toStringArray(g.include_all),
    ]);
    payload.filters.groupfamily_tags.include_any = uniq([
      ...payload.filters.groupfamily_tags.include_any,
      ...toStringArray(g.include_any),
    ]);
    payload.filters.groupfamily_tags.exclude = uniq([
      ...payload.filters.groupfamily_tags.exclude,
      ...toStringArray(g.exclude),
    ]);
  }
