const oldTitle =
  clean(parsed?.product?.name) ||
  clean(parsed?.product) ||
  clean(parsed?.title) ||
  "";

const oldTranslator =
  clean(parsed?.filters?.translator_or_playtime) ||
  clean(parsed?.filters?.translator) ||
  clean(parsed?.translator_or_playtime) ||
  clean(parsed?.translator);

