const input = $json;

// Tehran time now
const dtf = new Intl.DateTimeFormat('en-US', {
  timeZone: 'Asia/Tehran',
  hour12: false,
  year: 'numeric',
  month: '2-digit',
  day: '2-digit',
  weekday: 'short',
  hour: '2-digit',
  minute: '2-digit'
});

const parts = dtf.formatToParts(new Date());
const get = (type) => parts.find(p => p.type === type)?.value;

const hour = parseInt(get('hour') || '0', 10);
const minute = parseInt(get('minute') || '0', 10);
const weekday = get('weekday') || '';
const dateStr = `${get('year')}-${get('month')}-${get('day')}`;
const timeStr = `${String(hour).padStart(2,'0')}:${String(minute).padStart(2,'0')}`;

const mins = hour * 60 + minute;

// Store hours: 09:30–22:00
const storeOpen = (mins >= (9*60+30)) && (mins < (22*60));
// Support hours: 09:30–21:30
const supportOpen = (mins >= (9*60+30)) && (mins < (21*60+30));

return [{
  json: {
    ...input,
    tehran_now: { date: dateStr, time: timeStr, weekday },
    is_store_open_now: storeOpen,
    is_support_open_now: supportOpen
  }
}];

