const msg = ($json.message || $json.query || $json.text || '').toString();

// if order_number already provided by widget, keep it
let orderNumber = ($json.order_number || '').toString().trim();

// otherwise try to extract from message
if (!orderNumber) {
  // Persian/English digits → normalize
  const toEn = s => s
    .replace(/[۰-۹]/g, d => '۰۱۲۳۴۵۶۷۸۹'.indexOf(d))
    .replace(/[٠-٩]/g, d => '٠١٢٣٤٥٦٧٨٩'.indexOf(d));

  const m2 = toEn(msg);

  // adjust length based on your real order format
  const match = m2.match(/\b\d{5,12}\b/);
  if (match) orderNumber = match[0];
}

return [{ ...$json, order_number: orderNumber }];

